import React, { useMemo, useState } from 'react';
import type { Page, Teacher, Student, Guardian } from '../types';
import { Role } from '../types';
import { SIDEBAR_ITEMS, LogoutIcon } from '../constants';

interface SidebarProps {
  currentPage: Page;
  setCurrentPage: (page: Page) => void;
  currentUser: Teacher | Student | Guardian;
  onLogout: () => void;
  icfesDrillSettings?: { isActive: boolean, grades: string[] };
  isMobileOpen: boolean;
  setIsMobileOpen: (isOpen: boolean) => void;
}

const PAGE_ACCESS: Partial<Record<Role, Page[]>> = {
  [Role.ADMIN]: ['Dashboard', 'Classroom', 'Incidents', 'Psychology', 'Secretaria', 'TutorMode', 'Communication', 'Assessments', 'Calificaciones', 'Consolidado', 'AcademicDashboard', 'Resources', 'Eventos', 'Profile', 'Settings', 'Rectory', 'InstitutionProfile', 'StudentPortal', 'SimulacroICFES'],
  [Role.RECTOR]: ['Dashboard', 'Incidents', 'Psychology', 'Secretaria', 'Communication', 'Rectory', 'Calificaciones', 'Consolidado', 'AcademicDashboard', 'Resources', 'Eventos', 'Profile', 'Settings', 'InstitutionProfile', 'SimulacroICFES', 'TutorMode'],
  [Role.COORDINATOR]: ['Dashboard', 'Incidents', 'Psychology', 'Secretaria', 'Communication', 'Calificaciones', 'Consolidado', 'AcademicDashboard', 'Resources', 'Eventos', 'Profile', 'Settings', 'InstitutionProfile', 'SimulacroICFES', 'TutorMode'],
  [Role.TEACHER]: ['Dashboard', 'Classroom', 'Communication', 'Assessments', 'Calificaciones', 'Consolidado', 'Resources', 'Eventos', 'Profile', 'Settings', 'TutorMode'],
  [Role.STUDENT]: ['Dashboard', 'StudentPortal', 'Resources', 'Eventos', 'Profile', 'TutorMode'],
  [Role.PSYCHOLOGY]: ['Dashboard', 'Psychology', 'Communication', 'Resources', 'Profile', 'Settings'],
  [Role.GUARDIAN]: ['ParentPortal', 'Communication', 'Profile', 'Settings', 'Eventos'],
};

const Sidebar: React.FC<SidebarProps> = ({ currentPage, setCurrentPage, currentUser, onLogout, icfesDrillSettings, isMobileOpen, setIsMobileOpen }) => {
  // State for the floating tooltip in compact mode
  const [hoveredItem, setHoveredItem] = useState<{ label: string, top: number } | null>(null);

  const visibleItems = useMemo(() => {
    if (!currentUser) return [];

    const allowedPages = PAGE_ACCESS[currentUser.role] || [];
    return SIDEBAR_ITEMS.filter(item => allowedPages.includes(item.name));
  }, [currentUser]);

  const handleNavigation = (page: Page) => {
    setCurrentPage(page);
    // Close sidebar on navigation, especially for mobile
    setIsMobileOpen(false);
  };

  return (
    <>
      {/* Mobile Backdrop */}
      {isMobileOpen && (
        <div
          className="fixed inset-0 bg-black bg-opacity-50 z-40 lg:hidden backdrop-blur-sm"
          onClick={() => setIsMobileOpen(false)}
          aria-hidden="true"
        />
      )}

      {/* Sidebar Container */}
      <div
        className={`bg-primary text-white flex flex-col fixed inset-y-0 left-0 z-50 transition-all duration-300 ease-in-out
          transform ${isMobileOpen ? 'translate-x-0' : '-translate-x-full'} 
          w-64 lg:w-20 xl:w-64
          lg:relative lg:translate-x-0 shadow-2xl`}
      >
        {/* Header / Logo */}
        <div className="flex items-center justify-center h-20 border-b border-white/10 flex-shrink-0 transition-all duration-300 bg-primary-focus/20">
          <h1 className="text-xl font-bold hidden xl:block tracking-wide">AULA INTEGRAL</h1>
          <h1 className="text-xl font-bold xl:hidden">AIM</h1>
        </div>

        {/* Navigation Items */}
        <nav className="flex-1 px-3 py-6 space-y-2 overflow-y-auto scrollbar-thin scrollbar-thumb-primary-focus scrollbar-track-transparent">
          {visibleItems.map((item) => (
            <a
              key={item.name}
              href="#"
              onClick={(e) => {
                e.preventDefault();
                handleNavigation(item.name);
              }}
              onMouseEnter={(e) => {
                  const rect = e.currentTarget.getBoundingClientRect();
                  setHoveredItem({ label: item.label, top: rect.top + rect.height / 2 });
              }}
              onMouseLeave={() => setHoveredItem(null)}
              className={`group flex items-center p-3 rounded-xl transition-all duration-200 lg:justify-center xl:justify-start relative ${
                currentPage === item.name
                  ? 'bg-white text-primary shadow-md font-bold'
                  : 'text-blue-100 hover:bg-white/10 hover:text-white'
              }`}
              title={item.label} // Native tooltip fallback
            >
              <item.icon className={`h-6 w-6 flex-shrink-0 transition-transform duration-200 ${currentPage === item.name ? 'scale-110' : 'group-hover:scale-110'}`} />
              <span className="ml-4 font-medium hidden xl:block whitespace-nowrap">{item.label}</span>

              {/* Active Indicator Strip (Mobile/XL) */}
              {currentPage === item.name && (
                  <span className="absolute left-0 top-1/2 -translate-y-1/2 h-8 w-1 bg-secondary rounded-r-full xl:hidden"></span>
              )}
            </a>
          ))}
        </nav>

        {/* Logout Section */}
        <div className="px-3 py-6 mt-auto border-t border-white/10 bg-primary-focus/10">
          <a
              href="#"
              onClick={(e) => {
                  e.preventDefault();
                  onLogout();
              }}
              onMouseEnter={(e) => {
                  const rect = e.currentTarget.getBoundingClientRect();
                  setHoveredItem({ label: "Cerrar Sesión", top: rect.top + rect.height / 2 });
              }}
              onMouseLeave={() => setHoveredItem(null)}
              className="flex items-center p-3 rounded-xl transition-colors duration-200 text-blue-100 hover:bg-red-500/90 hover:text-white lg:justify-center xl:justify-start group"
          >
              <LogoutIcon className="h-6 w-6 flex-shrink-0 group-hover:animate-pulse" />
              <span className="ml-4 font-medium hidden xl:block whitespace-nowrap">Cerrar Sesión</span>
          </a>
        </div>

        {/* Footer info (Desktop XL only) */}
        <div className="pb-4 pt-2 text-center text-[10px] text-blue-200/60 hidden xl:block">
          <p className="font-semibold tracking-wider uppercase">EduFuturo</p>
          <p>v1.0.0</p>
        </div>
      </div>

      {/* Floating Tooltip (Visible only on LG screens where text is hidden) */}
      {hoveredItem && (
          <div 
              className="fixed z-[60] left-20 ml-4 px-3 py-2 bg-gray-900 text-white text-xs font-semibold rounded-md shadow-xl pointer-events-none transform -translate-y-1/2 animate-fade-in hidden lg:block xl:hidden whitespace-nowrap"
              style={{ top: hoveredItem.top }}
          >
              {hoveredItem.label}
              {/* Tooltip Arrow */}
              <div className="absolute left-0 top-1/2 -translate-x-1 -translate-y-1/2 w-2 h-2 bg-gray-900 rotate-45"></div>
          </div>
      )}
    </>
  );
};

export default Sidebar;

